  .site-head__nav ul { gap: calc(24 * var(--u, 1px)); }
  .hd-search { position: absolute; left: calc(1006 * var(--u, 1px)); top: calc(84 * var(--u, 1px)); width: calc(161 * var(--u, 1px)); height: calc(29 * var(--u, 1px)); }
  .hd-search input { padding: 0 calc(12 * var(--u, 1px)); font-family: 'Open Sans', sans-serif; font-weight: 700; font-size: calc(13 * var(--u, 1px)); line-height: calc(17.7 * var(--u, 1px)); }
