@media (max-width: 1023px) {
  .site-head > .fx { display: grid; grid-template-columns: 1fr auto; row-gap: 18px; gap: 18px 0; padding: 10px 20px; align-items: center; }
  .hd-logo img { width: 118px; height: 31px; object-fit: cover; }
  .site-head__toggle { display: inline-flex; justify-self: end; position: relative; z-index: 30; }
  .hd-lang { grid-row: 2; min-height: 18px; font-family: 'Montserrat', sans-serif; font-weight: 500; font-size: 13px; line-height: 15.6px; }
  .hd-lang ul { gap: 17px; }
  .hd-account { grid-row: 2; justify-self: end; font-family: 'Montserrat', sans-serif; font-weight: 500; font-size: 13px; line-height: 15.6px; }
  .hd-search, .hd-btn, .hd-phone { display: none; }
  /* Off-canvas drawer (Figma has no open-menu design). */
  .site-head__nav { position: fixed; inset: 0; z-index: 25; padding: 96px 20px 20px; background: #FFFFFF; transform: translateX(100%); transition: transform .3s ease; font-family: 'Open Sans', sans-serif; font-weight: 600; font-size: 18px; line-height: 28px; }
  .site-head__nav.is-open { transform: translateX(0); }
  .site-head__nav ul { flex-direction: column; gap: 16px; }
}

