.db-panel { box-sizing: border-box; background: rgba(196, 196, 196, 0.15); }
.db-h1 { margin: 0; font-family: 'Freeman', sans-serif; font-weight: 400; font-size: 24px; line-height: 32px; color: #000000; text-transform: uppercase; }
.db-lead { margin: 0; font-family: 'Open Sans', sans-serif; font-weight: 400; color: #000000; }
.db-stats, .db-tools { margin: 0; padding: 0; list-style: none; }
.db-stat { position: relative; box-sizing: border-box; background: #00B3F0; border-radius: 8px; color: #FFFFFF; }
.db-num { position: absolute; font-family: 'Freeman', sans-serif; font-weight: 400; font-size: 68px; line-height: 46px; }
.db-label { position: absolute; font-family: 'Open Sans', sans-serif; font-weight: 700; font-size: 14px; line-height: 22px; }
.db-tool { display: flex; box-sizing: border-box; background: #FFFFFF; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.15); border-radius: 10px; }
.db-icon { display: flex; align-items: center; justify-content: center; flex: none; width: 84px; height: 85px; background: rgba(249, 255, 67, 0.25); border-radius: 5px; box-shadow: 2px 0 4px rgba(0, 0, 0, 0.35); }
.db-icon img { display: block; border-radius: 10px; }
.db-tool-h { margin: 0; font-family: 'Open Sans', sans-serif; font-weight: 700; font-size: 14px; line-height: 22px; }
.db-tool-h a { color: #0065B3; text-decoration: none; }
.db-tool-p { margin: 0; font-family: 'Open Sans', sans-serif; font-weight: 300; font-size: 14px; color: #000000; }
.db-acc-h { margin: 0; font-family: 'Freeman', sans-serif; font-weight: 400; font-size: 20px; line-height: 50px; color: #000000; text-transform: uppercase; }
.db-acc-btns { display: flex; }
.db-btn { display: flex; align-items: center; justify-content: center; box-sizing: border-box; border-radius: 5px; font-family: 'Freeman', sans-serif; font-weight: 400; font-size: 16px; }
.db-btn--1 { background: #0065B3; color: #FFFFFF; }
.db-btn--2 { color: #00B3F0; }
.db-btn--3 { color: #0065B3; }
@media (max-width: 1023px) {
  .rs.db-acc.db-acc, .rs.db-acc.db-acc > .fx { background: #F6F6F6; }
  .db-panel { display: flex; flex-direction: column; gap: 20px; padding: 32px; border-radius: 12px; }
  .db-lead { font-size: 11px; line-height: 18px; }
  .db-grid, .db-stats, .db-tools { display: flex; flex-direction: column; gap: 20px; }
  .db-stat { height: 115px; }
  .db-num { left: 35px; top: 35px; }
  .db-label { left: 92px; top: 71px; }
  .db-tool { flex-direction: column; gap: 24px; padding: 15px; }
  .db-tool-p { line-height: 18px; }
  .db-acc > .fx { padding: 22px 20px; }
  .db-acc-btns { flex-direction: column; gap: 12px; margin: 22px -20px 0; padding: 44px 20px; background: #FCFEFF; }
  .db-btn { height: 50px; }
  .db-btn--2, .db-btn--3 { border: 1px solid #00B3F0; }
  .db > .fx, .db-acc > .fx { max-width: 640px; margin: 0 auto; box-sizing: border-box; }
