  .db-panel { width: calc(1250.0 * var(--u, 1px)); height: calc(540.0 * var(--u, 1px)); border-radius: calc(15 * var(--u, 1px)); padding: calc(37.0 * var(--u, 1px)) 0 0 calc(45.0 * var(--u, 1px)); }
